## 5. React Hook Example

```typescript
// src/hooks/useChat.ts
import { useEffect, useRef, useState, useCallback } from 'react';
import { useAuth } from './useAuth'; // your existing auth hook
import {
  connectChat,
  disconnectChat,
  subscribeToRoom,
  subscribeToTyping,
  subscribeToPresence,
  sendMessageWs,
  sendTypingIndicator,
} from '../services/chatWebSocket';
import chatApi from '../services/chatApi';

interface ChatMessage {
  id: string;
  room_id: string;
  sender_id: string;
  type: string;
  body: string;
  created_at: string;
  edited: boolean;
  deleted: boolean;
}

export const useChat = (roomId: string | null) => {
  const { token, user } = useAuth();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [typingUsers, setTypingUsers] = useState<Set<string>>(new Set());
  const [connected, setConnected] = useState(false);
  const subsRef = useRef<any[]>([]);

  // Connect WebSocket
  useEffect(() => {
    if (!token || !user?.organization_id) return;

    connectChat(
      token,
      user.organization_id,
      () => setConnected(true),
      () => setConnected(false)
    );

    return () => {
      disconnectChat();
    };
  }, [token, user?.organization_id]);

  // Subscribe to room
  useEffect(() => {
    if (!connected || !roomId || !user?.organization_id) return;

    // Load history
    chatApi
      .get(`/rooms/${roomId}/messages`, { params: { page: 0, size: 50 } })
      .then((res) => {
        setMessages(res.data.content.reverse()); // oldest first
      });

    // Subscribe to new messages
    const msgSub = subscribeToRoom(user.organization_id, roomId, (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    // Subscribe to typing
    const typingSub = subscribeToTyping(user.organization_id, roomId, (event) => {
      setTypingUsers((prev) => {
        const next = new Set(prev);
        if (event.typing) {
          next.add(event.user_id);
        } else {
          next.delete(event.user_id);
        }
        return next;
      });
    });

    subsRef.current = [msgSub, typingSub].filter(Boolean);

    return () => {
      subsRef.current.forEach((sub) => sub?.unsubscribe());
      subsRef.current = [];
    };
  }, [connected, roomId, user?.organization_id]);

  const sendMessage = useCallback(
    (body: string) => {
      if (roomId) sendMessageWs(roomId, body);
    },
    [roomId]
  );

  const sendTyping = useCallback(
    (typing: boolean) => {
      if (roomId) sendTypingIndicator(roomId, typing);
    },
    [roomId]
  );

  return { messages, typingUsers, connected, sendMessage, sendTyping };
};
```

