  id: string;
  room_id: string;
  sender_id: string;
  sender_name: string | null;
  type: 'TEXT' | 'FILE' | 'SYSTEM';
  body: string | null;
  parent_message_id: string | null;
  file_url: string | null;
  file_name: string | null;
  file_size: number | null;
  file_content_type: string | null;
  edited: boolean;
  deleted: boolean;
  created_at: string;
  edited_at: string | null;
}

export interface TypingEvent {
  room_id: string;
  user_id: string;
  user_name: string | null;
  typing: boolean;
}

export interface WebSocketEventDto {
  event: string;        // USER_ONLINE, USER_OFFLINE, ROOM_CREATED, MEMBER_ADDED, MEMBER_REMOVED, MESSAGE_DELETED, READ_RECEIPT
  user_id: string;
  room_id: string | null;
  message_id: string | null;
  timestamp: number;
}

export interface CreateRoomRequest {
  type: 'PRIVATE' | 'GROUP';
  name?: string;
  description?: string;
  member_user_ids: string[];
}

export interface SendMessageRequest {
  room_id: string;
  body?: string;
  type?: 'TEXT' | 'FILE';
  parent_message_id?: string;
  file_url?: string;
  file_name?: string;
  file_size?: number;
  file_content_type?: string;
}

export interface FileUploadResponse {
  file_url: string;
  file_name: string;
  file_size: number;
  content_type: string;
}

export interface PageResponse<T> {
  content: T[];
  page: number;
  size: number;
  total_elements: number;
  total_pages: number;
  first: boolean;
  last: boolean;
}
